const allItems = $input.all();
const candlesPerCoin = 250;

if (allItems.length !== symbols.length * candlesPerCoin) {
  throw new Error(`Beklenen 3000 mum, gelen: ${allItems.length}`);
}

function emaSeries(values, period) {
  const k = 2 / (period + 1);
  const result = [values[0]];

  for (let i = 1; i < values.length; i++) {
    result.push(values[i] * k + result[i - 1] * (1 - k));
  }

  return result;
}

function calculateRSI(values, period = 14) {
  let gains = 0;
  let losses = 0;

  for (let i = 1; i <= period; i++) {
    const change = values[i] - values[i - 1];
    gains += Math.max(change, 0);
    losses += Math.max(-change, 0);
  }

  let avgGain = gains / period;
  let avgLoss = losses / period;

  for (let i = period + 1; i < values.length; i++) {
    const change = values[i] - values[i - 1];
    avgGain = (avgGain * 13 + Math.max(change, 0)) / 14;
    avgLoss = (avgLoss * 13 + Math.max(-change, 0)) / 14;
  }

  if (avgLoss === 0) return 100;
  return 100 - (100 / (1 + avgGain / avgLoss));
}

return symbols.map((symbol, index) => {
  const group = allItems.slice(
    index * candlesPerCoin,
    (index + 1) * candlesPerCoin
  );

  let candles = group.map(item => ({
    openTime: Number(item.json[0]),
    closeTime: Number(item.json[6]),
    close: Number(item.json[4]),
    high: Number(item.json[2]),
    low: Number(item.json[3]),
    volume: Number(item.json[5])
  }));

  const now = Date.now();

  candles = candles.filter(c => c.closeTime < now);

  if (candles.length < 200) {
    throw new Error(`${symbol}: Yeterli kapanmış mum yok.`);
  }

  const closes = candles.map(c => c.close);

  const ema9 = emaSeries(closes, 9);
  const ema21 = emaSeries(closes, 21);
  const ema50 = emaSeries(closes, 50);
  const ema200 = emaSeries(closes, 200);

  const previousDiff = ema9.at(-2) - ema21.at(-2);
  const currentDiff = ema9.at(-1) - ema21.at(-1);

  let crossover = "NO CROSS";

  if (previousDiff <= 0 && currentDiff > 0) crossover = "BULLISH CROSS";
  if (previousDiff >= 0 && currentDiff < 0) crossover = "BEARISH CROSS";

  const ema12 = emaSeries(closes, 12);
  const ema26 = emaSeries(closes, 26);

  const macdSeries = ema12.map((v, i) => v - ema26[i]);
  const signalSeries = emaSeries(macdSeries, 9);

  const last20 = closes.slice(-20);
  const middle = last20.reduce((a, b) => a + b, 0) / 20;

  const variance = last20.reduce(
    (sum, value) => sum + Math.pow(value - middle, 2), 0
  ) / 20;

  const deviation = Math.sqrt(variance);

  return {
    json: {
      symbol,
      currentPrice: closes.at(-1),
      lastClosedCandle: new Date(candles.at(-1).closeTime).toISOString(),
      indicators: {
        RSI_14: Number(calculateRSI(closes).toFixed(2)),
        MACD: Number(macdSeries.at(-1).toFixed(8)),
        MACD_Signal: Number(signalSeries.at(-1).toFixed(8)),
        MACD_Histogram: Number((macdSeries.at(-1) - signalSeries.at(-1)).toFixed(8)),
        EMA_9: Number(ema9.at(-1).toFixed(8)),
        EMA_21: Number(ema21.at(-1).toFixed(8)),
        EMA_50: Number(ema50.at(-1).toFixed(8)),
        EMA_200: Number(ema200.at(-1).toFixed(8)),
        EMA_Crossover: crossover,
        Bollinger_Upper: Number((middle + 2 * deviation).toFixed(8)),
        Bollinger_Middle: Number(middle.toFixed(8)),
        Bollinger_Lower: Number((middle - 2 * deviation).toFixed(8))
      }
    }
  };
});

