const items = $input.all();

return items.map(item => {
  const analysis = item.json.analysis;
  const technicalData = item.json.technicalData || [];

  const technicalMap = new Map(
    technicalData.map(coin => [coin.symbol, coin])
  );

  const validatedSignals = (analysis.signals || []).map(signal => {
    const technical = technicalMap.get(signal.symbol);

    if (!technical?.indicators) {
      return {
        ...signal,
        signal: 'WAIT',
        strength: 0,
        reason: 'Teknik veri bulunamadı. Sinyal doğrulanamadı.'
      };
    }

    const indicators = technical.indicators;
    const reason = signal.reason || '';
    const checks = [];

    const crossover = String(
      indicators.EMA_Crossover || ''
    ).toUpperCase();

    const rsi = Number(indicators.RSI_14);
    const macd = Number(indicators.MACD);
    const histogram = Number(indicators.MACD_Histogram);

    const price = Number(technical.currentPrice);
    const ema9 = Number(indicators.EMA_9);
    const ema21 = Number(indicators.EMA_21);
    const ema50 = Number(indicators.EMA_50);

    // 1. Teknik veri kontrolü
    if (
      ![
        rsi, macd, histogram, price,
        ema9, ema21, ema50
      ].every(Number.isFinite)
    ) {
      return {
        ...signal,
        signal: 'WAIT',
        strength: 0,
        reason: 'Teknik göstergeler eksik veya geçersiz.'
      };
    }

    // 2. Zaman dilimi kontrolü
    if (/günlük|daily|1d/i.test(reason)) {
      checks.push('Günlük veri mevcut değil.');
    }

    // 3. RSI açıklama kontrolü
    const rsiMatch = reason.match(
      /RSI\s*(?:değeri\s*)?(\d+(?:[.,]\d+)?)/i
    );

    if (rsiMatch) {
      const claimedRSI = Number(
        rsiMatch[1].replace(',', '.')
      );

      if (Math.abs(claimedRSI - rsi) > 3) {
        checks.push('RSI iddiası gerçek verilerle uyuşmuyor.');
      }
    }

    // 4. EMA kesişimi açıklama kontrolü
    const isBullishCross = /bullish cross/i.test(reason);
    const isBearishCross = /bearish cross/i.test(reason);

    if (isBullishCross || isBearishCross) {
      if (
        crossover === 'NO CROSS' ||
        (isBullishCross && !crossover.includes('BULLISH')) ||
        (isBearishCross && !crossover.includes('BEARISH'))
      ) {
        checks.push('EMA kesişimi doğrulanamadı.');
      }
    }

    // 5. MACD açıklama kontrolü
    if (/MACD negatif/i.test(reason) && macd >= 0) {
      checks.push('MACD negatif iddiası yanlış.');
    }

    if (/MACD pozitif/i.test(reason) && macd <= 0) {
      checks.push('MACD pozitif iddiası yanlış.');
    }

    // 6. MACD Histogram açıklama kontrolü
    if (
      /MACD histogram negatif/i.test(reason) &&
      histogram >= 0
    ) {
      checks.push('MACD Histogram negatif iddiası yanlış.');
    }

    if (
      /MACD histogram pozitif/i.test(reason) &&
      histogram <= 0
    ) {
      checks.push('MACD Histogram pozitif iddiası yanlış.');
    }

    // 7. Bollinger Bands konum kontrolü
    const upper = Number(indicators.Bollinger_Upper);
    const middle = Number(indicators.Bollinger_Middle);
    const lower = Number(indicators.Bollinger_Lower);

    if (
      ![upper, middle, lower].every(Number.isFinite)
    ) {
      checks.push('Bollinger verileri eksik veya geçersiz.');
    } else {

      if (
        /Bollinger (?:üst|upper) band(?:ının|inin)? (?:üzerinde|üstünde)/i.test(reason) &&
        price <= upper
      ) {
        checks.push('Fiyat üst bandın üzerinde değil.');
      }

      if (
        /Bollinger (?:alt|lower) band(?:ının|inin)? (?:altında|altına)/i.test(reason) &&
        price >= lower
      ) {
        checks.push('Fiyat alt bandın altında değil.');
      }

      if (
        /Bollinger orta band(?:ının|inin)? altında/i.test(reason) &&
        price >= middle
      ) {
        checks.push('Fiyat orta bandın altında değil.');
      }

      if (
        /Bollinger orta band(?:ının|inin)? üzerinde/i.test(reason) &&
        price <= middle
      ) {
        checks.push('Fiyat orta bandın üzerinde değil.');
      }

      if (
        /Bollinger band(?:ı|ları) içerisinde/i.test(reason) &&
        (price < lower || price > upper)
      ) {
        checks.push('Fiyat Bollinger bantları içerisinde değil.');
      }

      // Alt ve orta bant arasındaki konum
      if (
        /Bollinger alt(?: ve|\/)orta band(?:ı|ları) arasında|alt ve orta bantları arasında/i.test(reason) &&
        (price < lower || price > middle)
      ) {
        checks.push('Fiyat alt ve orta Bollinger bandı arasında değil.');
      }

      // Orta ve üst bant arasındaki konum
      if (
        /Bollinger orta(?: ve|\/)üst band(?:ı|ları) arasında|orta ve üst bantları arasında/i.test(reason) &&
        (price < middle || price > upper)
      ) {
        checks.push('Fiyat orta ve üst Bollinger bandı arasında değil.');
      }
    }

    // 8. EMA ve MACD Histogram uyum kontrolü
    if (
      crossover.includes('BEARISH') &&
      histogram > 0
    ) {
      checks.push(
        'Bearish EMA kesişimine rağmen MACD Histogram pozitif.'
      );
    }

    if (
      crossover.includes('BULLISH') &&
      histogram < 0
    ) {
      checks.push(
        'Bullish EMA kesişimine rağmen MACD Histogram negatif.'
      );
    }

    // 9. Bağımsız LONG / SHORT yön kontrolü
    const bearishConditions = [
      rsi < 45,
      ema9 < ema21,
      histogram < 0,
      price < ema50
    ];

    const bullishConditions = [
      rsi > 55,
      ema9 > ema21,
      histogram > 0,
      price > ema50
    ];

    const bearishCount = bearishConditions.filter(Boolean).length;
    const bullishCount = bullishConditions.filter(Boolean).length;


    // 10. Bağımsız teknik uyum puanı
    let technicalBias = 'NEUTRAL';

    if (bearishCount > bullishCount) {
      technicalBias = 'BEARISH';
    } else if (bullishCount > bearishCount) {
      technicalBias = 'BULLISH';
    }

const technicalAlignmentScore = Math.round(
  Math.max(bearishCount, bullishCount) * 25
);

    let finalSignal = signal.signal;
    let finalStrength = Math.max(
      0,
      Math.min(100, Number(signal.strength) || 0)
    );

    let finalReason = reason;

    if (
      signal.signal === 'LONG' &&
      bearishCount >= 3
    ) {
      finalSignal = 'WAIT';
      finalStrength = 0;
      finalReason =
        'Bağımsız teknik doğrulama başarısız: ' +
        bearishCount +
        '/4 gösterge bearish yönde. LONG sinyali WAIT olarak değiştirildi.';
    }

    if (
      signal.signal === 'SHORT' &&
      bullishCount >= 3
    ) {
      finalSignal = 'WAIT';
      finalStrength = 0;
      finalReason =
        'Bağımsız teknik doğrulama başarısız: ' +
        bullishCount +
        '/4 gösterge bullish yönde. SHORT sinyali WAIT olarak değiştirildi.';
    }

    // 10. Açıklama doğrulaması başarısızsa WAIT
    if (checks.length > 0) {
      finalSignal = 'WAIT';
      finalStrength = 0;
      finalReason =
        'Doğrulama başarısız: ' + checks.join(' ');
    }

    return {
      ...signal,
      signal: finalSignal,
      strength: finalStrength,
      reason: finalReason,
      technicalBias,
      technicalAlignmentScore,
      bearishConditions: bearishCount,
      bullishConditions: bullishCount
    };
  });

  return {
    json: {
      ...item.json,
      analysis: {
        ...analysis,
        signals: validatedSignals
      }
    }
  };
});
